-- Core domain model
CREATE TABLE users (id UUID PRIMARY KEY, email TEXT UNIQUE, username TEXT UNIQUE, display_name TEXT, avatar_url TEXT, role TEXT, status TEXT, email_verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE creator_profiles (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), display_name TEXT, bio TEXT, website_url TEXT, verification_status TEXT, payout_status TEXT, tax_status TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE games (id UUID PRIMARY KEY, creator_profile_id UUID REFERENCES creator_profiles(id), slug TEXT UNIQUE, title TEXT, short_description TEXT, description_markdown TEXT, status TEXT, visibility TEXT, content_rating TEXT, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE game_releases (id UUID PRIMARY KEY, game_id UUID REFERENCES games(id), version TEXT, status TEXT, release_notes TEXT, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE game_platforms (id UUID PRIMARY KEY, game_release_id UUID REFERENCES game_releases(id), platform TEXT, architecture TEXT, access_type TEXT, executable_path TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE tags (id UUID PRIMARY KEY, slug TEXT UNIQUE, name TEXT, category TEXT, moderation_status TEXT);
CREATE TABLE game_tags (game_id UUID REFERENCES games(id), tag_id UUID REFERENCES tags(id), created_at TIMESTAMPTZ DEFAULT NOW(), PRIMARY KEY (game_id, tag_id));
CREATE TABLE price_plans (id UUID PRIMARY KEY, game_id UUID REFERENCES games(id), currency TEXT, amount_minor INTEGER, minimum_amount_minor INTEGER, pricing_type TEXT, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ);
CREATE TABLE orders (id UUID PRIMARY KEY, buyer_user_id UUID REFERENCES users(id), currency TEXT, subtotal_minor INTEGER, tax_minor INTEGER, total_minor INTEGER, status TEXT, payment_provider TEXT, provider_reference TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE order_items (id UUID PRIMARY KEY, order_id UUID REFERENCES orders(id), game_id UUID REFERENCES games(id), creator_profile_id UUID REFERENCES creator_profiles(id), amount_minor INTEGER, revenue_share_minor INTEGER);
CREATE TABLE entitlements (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), game_id UUID REFERENCES games(id), order_item_id UUID REFERENCES order_items(id), entitlement_type TEXT, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE upload_sessions (id UUID PRIMARY KEY, creator_profile_id UUID REFERENCES creator_profiles(id), game_id UUID REFERENCES games(id), status TEXT, expected_bytes BIGINT, uploaded_bytes BIGINT, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE artifacts (id UUID PRIMARY KEY, game_release_id UUID REFERENCES game_releases(id), platform TEXT, object_key TEXT, size_bytes BIGINT, sha256 TEXT, mime_type TEXT, scan_status TEXT, processing_status TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE download_events (id UUID PRIMARY KEY, artifact_id UUID REFERENCES artifacts(id), user_id UUID REFERENCES users(id), country TEXT, user_agent_hash TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE TABLE comments (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), game_id UUID REFERENCES games(id), parent_comment_id UUID REFERENCES comments(id), body TEXT, status TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE ratings (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), game_id UUID REFERENCES games(id), rating INTEGER, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, game_id));
CREATE TABLE reports (id UUID PRIMARY KEY, reporter_user_id UUID REFERENCES users(id), target_type TEXT, target_id TEXT, reason TEXT, status TEXT, priority TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE moderation_actions (id UUID PRIMARY KEY, moderator_user_id UUID REFERENCES users(id), target_type TEXT, target_id TEXT, action TEXT, reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
